// Add and subtract a delta from a moby field, storing results
void initialize_moby_grounding(char *moby) {
    float delta = 0.2f;
    float val = *(float *)(moby + 0x18);
    *(float *)(moby + 0x84) = val - delta;
    *(float *)(moby + 0x88) = val + delta;
}
